11	// Polyfill window and animation frames for Three.js headless context
12	if (typeof globalThis.window === 'undefined') {
13		(globalThis as any).window = globalThis;
14		if (!globalThis.requestAnimationFrame) {
15			globalThis.requestAnimationFrame = (cb: FrameRequestCallback) => setTimeout(() => cb(Date.now()), 1000 / 60) as any;
16			globalThis.cancelAnimationFrame = (id: number) => clearTimeout(id as any);
17		}
