37	export async function runServer(source: CacheFileSource, endpoint: string, auth: string) {
38		let backoff = 1;
39		while (true) {
40			let res = false;
41			try {
42				res = await runConnection(source, endpoint, auth);
43			} catch { }
44			if (!res) {
45				await delay(backoff * 1000);
46				backoff = Math.min(5 * 60, backoff * 2);
47			} else {
48				await delay(1000);
49				backoff = 1;
50			}
51		}
52	}
53	
54	
55	function runConnection(source: CacheFileSource, endpoint: string, auth: string) {
56		return new Promise<boolean>(async (done, err) => {
57			let engine = await EngineCache.create(source);
58			let ws = new WebSocket(endpoint);
59			let didopen = false;
60			ws.onopen = () => { ws.send(auth); didopen = true; };
61			ws.onclose = () => done(didopen);
62			ws.onerror = () => done(didopen);
63			ws.onmessage = async (msg) => {
64				let packet = JSON.parse(msg.data);
65				try {
66					let scene = await ThreejsSceneCache.create(engine);
67					if (packet.type == "player") {
68						let ava = await renderAppearance(scene, "player", packet.data);
69						ws.send(JSON.stringify({
70							reqid: packet.reqid,
71							type: "modelbase64",
72							data: {
73								model: ava.modelfile.toString("base64"),
74								image: ava.imgfile.toString("base64")
75							}
76						}));
77					} else if (packet.type == "appearance") {
78						let ava = await renderAppearance(scene, "appearance", packet.data);
79						ws.send(JSON.stringify({
80							reqid: packet.reqid,
81							type: "modelbase64",
82							data: {
83								model: ava.modelfile.toString("base64"),
84								image: ava.imgfile.toString("base64")
85							}
86						}));
87					} else {
88						throw new Error("unknown packet type " + packet.type);
89					}
90				}
91				catch (e) {
92					ws.send(JSON.stringify({
93						reqid: packet.reqid,
94						type: "err",
95						data: e + ""
96					}));
97				}
98			}
99		});
100	}
