102	export async function getRenderer(width: number, height: number, extraopts?: WebGLRendererParameters) {
103		let opts = Object.assign({ antialias: true, alpha: true } as WebGLRendererParameters, extraopts);
104	
105		let cnv: HTMLCanvasElement;
106		let ctx: WebGLRenderingContext | undefined = undefined;
107		if (typeof HTMLCanvasElement != "undefined") {
108			//browser/electron/puppeteer
109			cnv = document.createElement("canvas");
110			cnv.width = width;
111			cnv.height = height;
112		} else {
113			//nodejs "gl" implementation, currently not maintained
114			cnv = {
115				width, height,
116				clientWidth: width, clientHeight: height,
117				addEventListener: (event: string, cb: any) => { },
118				removeEventListener: (event: string, cb: any) => { },
119				getRootNode: () => cnv,
120				style: {}
121			} as any;
122			try {
123				ctx = __non_webpack_require__("gl")(width, height, opts);
124			} catch (e) {
125				console.error("gl initialization crash:", e);
126			}
127			if (!ctx) {
128				console.warn("gl initialization failed with opts, trying without opts...");
129				ctx = __non_webpack_require__("gl")(width, height);
130			}
131		}
132	
133		const { ThreeJsRenderer } = await import("../viewer/threejsrender.js") as any;
134		let render = new ThreeJsRenderer(cnv, { context: ctx, ...opts });
135	
136		// FIX: Force Three.js to use uniform-based skinning instead of texture-based skinning
137		// headless-gl only supports WebGL 1.0, but Three.js attempts to use texelFetch if it thinks
138		// float vertex textures are supported, causing shader compilation errors.
139		if (!document) {
140			render["renderer"].capabilities.floatVertexTextures = false;
141		}
142	
143		return render;
144	}
