146	export async function renderAppearance(scene: ThreejsSceneCache, mode: "player" | "appearance" | "item" | "npc" | "loc" | "spot" | "mat" | "map" | "sound" | "music" | "sprite", argument: string, headmodel = false, overrides: ModelModifications = {}, overrideAnimId?: number) {
147		let width = 500;
148		let height = 700;
149	
150		// Handle non-3D Assets first
151		if (mode == "sound" || mode == "music") {
152			const { parseMusic } = await import("../scripts/musictrack.js");
153			let major = (mode == "sound" ? cacheMajors.sounds : cacheMajors.music);
154			let ogg = await parseMusic(scene.engine.rawsource, major, +argument, null, true);
155			return { modelfile: ogg, imgfile: Buffer.alloc(0), metadata: { type: mode, id: argument } };
156		}
157		if (mode == "sprite") {
158			const { parseSprite } = await import("../3d/sprite.js");
159			let sprites = await parseSprite(await scene.engine.getFileById(cacheMajors.sprites, +argument));
160			let imgfile = await pixelsToImageFile(sprites[0].img as any, "png", 1);
161			return { modelfile: imgfile, imgfile, metadata: { type: "sprite", id: argument } };
162		}
163	
164		const { ThreeJsRenderer, exportThreeJsGltf } = await import("../viewer/threejsrender.js");
165		const { RSModel } = await import("../3d/modelnodes.js");
166		const { avatarToModel } = await import("../3d/avatar.js");
167	
168		let render = await getRenderer(width, height);
169		render.addSceneElement({
170			getSceneElements() {
171				return { options: { autoFrames: "never", hideFloor: true } };
172			}
173		});
174	
175		let meshdata: any;
176		if (mode == "player") {
177			let url = appearanceUrl(argument);
178			let appearance = "";
179			try {
180				appearance = await fetch(url).then(q => q.text());
181			} catch (e: any) {
182				throw new Error(`Avatar service blocked: ${e.message}. Consider using an appearance override string.`);
183			}
184			if (appearance.indexOf("404 - Page not found") != -1 || appearance.includes("303 See Other") || appearance.includes("Challenge")) {
185				throw new Error("player avatar not found or blocked by Jagex (303/Challenge detected).");
186			}
187			const { avatarToModel } = await import("../3d/avatar.js");
188			meshdata = await avatarToModel(scene.engine, avatarStringToBytes(appearance), headmodel);
189		} else if (mode == "appearance") {
190			const { avatarToModel } = await import("../3d/avatar.js");
191			meshdata = await avatarToModel(scene.engine, avatarStringToBytes(argument), headmodel);
192		} else if (mode as string == "item") {
193			if (isNaN(+argument)) { throw new Error("number expected"); }
194			const { itemToModel } = await import("../3d/modelnodes.js");
195			meshdata = await itemToModel(scene, +argument);
196		} else if (mode as string == "npc") {
197			if (isNaN(+argument)) { throw new Error("number expected"); }
198			const { npcToModel } = await import("../3d/modelnodes.js");
199			meshdata = await npcToModel(scene, { id: +argument, head: headmodel });
200		} else if (mode as string == "loc") {
201			if (isNaN(+argument)) { throw new Error("number expected"); }
202			const { locToModel } = await import("../3d/modelnodes.js");
203			meshdata = await locToModel(scene, +argument);
204		} else if (mode as string == "spot") {
205			if (isNaN(+argument)) { throw new Error("number expected"); }
206			const { spotAnimToModel } = await import("../3d/modelnodes.js");
207			meshdata = await spotAnimToModel(scene, +argument);
208		} else if (mode as string == "mat") {
209			if (isNaN(+argument)) { throw new Error("number expected"); }
210			const { materialToModel } = await import("../3d/modelnodes.js");
211			meshdata = await materialToModel(scene, +argument);
212		} else if (mode as string == "map") {
213			const { RSMapChunk } = await import("../3d/modelnodes.js");
214			let [x, z] = argument.split(",").map(Number);
215			let chunk = RSMapChunk.create(scene, x, z);
216			render.addSceneElement(chunk);
217			// Manual gltf export for map chunk since it's not a standard RSModel
218			await delay(100);
219			let gltfblob = await exportThreeJsGltf(render.getModelNode());
220			return { modelfile: Buffer.from(gltfblob), imgfile: Buffer.alloc(0), metadata: { type: mode, id: argument } };
221		} else {
222			throw new Error("unknown mode " + mode);
223		}
224	
225		// Apply overrides to model modifications
226		if (overrides.replaceColors || overrides.replaceMaterials) {
227			meshdata.models.forEach(m => {
228				if (overrides.replaceColors) {
229					m.mods.replaceColors = [...(m.mods.replaceColors || []), ...overrides.replaceColors];
230				}
231				if (overrides.replaceMaterials) {
232					m.mods.replaceMaterials = [...(m.mods.replaceMaterials || []), ...overrides.replaceMaterials];
233				}
234			});
235		}
236	
237		// Extract Semantic Metadata for NPCs/Items/Objects
238		let semantic: any = {};
239		try {
240			if (mode == "npc") {
241				let config: any = parse.npc.read(await scene.engine.getFileById(cacheMajors.npcs, +argument), scene.engine.rawsource);
242				console.log("NPC CONFIG CAPTURED:", JSON.stringify(config, null, 2));
243				semantic = {
244					name: config.name,
245					actions: [
246						config.actions_0, config.actions_1, config.actions_2, config.actions_3, config.actions_4,
247						config.members_actions_0, config.members_actions_1, config.members_actions_2, config.members_actions_3, config.members_actions_4
248					].filter(Boolean),
249					extra: config.extra
250				};
251			} else if (mode == "item") {
252				let config: any = parse.item.read(await scene.engine.getFileById(cacheMajors.items, +argument), scene.engine.rawsource);
253				console.log("ITEM CONFIG CAPTURED:", JSON.stringify(config, null, 2));
254				semantic = {
255					name: config.name,
256					actions: [
257						config.ground_actions_0, config.ground_actions_1, config.ground_actions_2, config.ground_actions_3, config.ground_actions_4,
258						config.widget_actions_0, config.widget_actions_1, config.widget_actions_2, config.widget_actions_3, config.widget_actions_4
259					].filter(Boolean),
260					extra: config.extra
261				};
262			} else if (mode == "loc") {
263				let config: any = parse.object.read(await scene.engine.getFileById(cacheMajors.objects, +argument), scene.engine.rawsource);
264				console.log("OBJECT CONFIG CAPTURED:", JSON.stringify(config, null, 2));
265				semantic = {
266					name: config.name,
267					actions: [config.actions_0, config.actions_1, config.actions_2, config.actions_3, config.actions_4].filter(Boolean),
268					extra: config.extra
269				};
270			}
271		} catch (e) { console.warn("metadata extraction failed:", e); }
272		// let player = await itemToModel(scene, 0);
273		let model = new RSModel(scene, meshdata.models, meshdata.name);
274		if (overrideAnimId !== undefined && !isNaN(overrideAnimId)) {
275			model.setAnimation(overrideAnimId);
276			console.log(`[KINEMATIC-BIND] Forcing model animation to sequence ${overrideAnimId}`);
277		} else if (meshdata.anims && !isNaN(meshdata.anims.default)) {
278			model.setAnimation(meshdata.anims.default);
279		}
280		render.addSceneElement(model);
281	
282		console.log("waiting for model to load...");
283		await model.model;
284		console.log("model loaded. setting camera...");
285		await delay(1);
286	
287		// Dynamic camera framing based on bounding box
288		const box = new (await import("three")).Box3().setFromObject(render.getModelNode());
289		const center = box.getCenter(new (await import("three")).Vector3());
290		const size = box.getSize(new (await import("three")).Vector3());
291		const maxDim = Math.max(size.x, size.y, size.z);
292		const fov = 45; // PerspectiveCamera fov is 45 in ThreeJsRenderer
293		const aspect = width / height;
294		// Calculate distance to fit the object
295		let distance = maxDim / (2 * Math.tan(Math.PI * fov / 360));
296		distance *= 1.2; // Add 20% margin
297	
298		render.setCameraPosition(new (await import("three")).Vector3(center.x, center.y + size.y * 0.1, center.z + distance));
299		render.setCameraLimits(center);
300	
301		console.log("exporting gltf...");
302		let gltfblob = await exportThreeJsGltf(render.getModelNode());
303		console.log("gltf exported. size:", gltfblob.byteLength);
304		let modelfile = Buffer.from(gltfblob);
305	
306		console.log("taking picture...");
307		let img: { data: Uint8ClampedArray; width: number; height: number };
308		try {
309			img = await render.takeScenePicture();
310			console.log("picture taken. size:", img.data.length);
311		} catch (e) {
312			console.error("taking picture failed:", e);
313			// Return a black dummy image so we don't crash the pedagogy loop
314			img = new (globalThis as any).ImageData(new Uint8ClampedArray(width * height * 4), width, height);
315		}
316		let imgfile = await pixelsToImageFile(img as any, "png", 1);
317		console.log("image compressed. size:", imgfile.length);
318	
319		try {
320			render.dispose();
321		} catch (e) {
322			// Silently ignore headless dispose errors.
323		}
324	
325		return { imgfile, modelfile, semantic };
326	}

1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { GameCacheLoader } from '../cache/sqlite';
