48	        let stderr = '';
49	
50	        child.stdout.on('data', (data) => {
51	            const chunk = data.toString();
52	            stdout += chunk;
53	
54	            // Phase 9: Real-time Substrate Visibility
55	            // If the chunk doesn't look like part of a JSON blob, it might be a log from the sub-tool
56	            if (!chunk.trim().startsWith('{') && !chunk.trim().startsWith('[')) {
57	                const lines = chunk.split('\n').filter((l: string) => l.trim());
58	                for (const line of lines) {
59	                    process.stdout.write(`\x1b[38;5;244m[RSMV_BRIDGE:OUT]\x1b[0m ${line}\n`);
60	                }
61	            }
62	        });
63	
64	        child.stderr.on('data', (data) => {
65	            const chunk = data.toString();
66	            stderr += chunk;
67	            const lines = chunk.split('\n').filter((l: string) => l.trim());
68	            for (const line of lines) {
69	                process.stderr.write(`\x1b[38;5;208m[RSMV_BRIDGE:ERR]\x1b[0m ${line}\n`);
70	            }
71	        });
72	
73	        const timer = setTimeout(() => {
74	            child.kill();
75	            logger.warn({ operation, timeout: TIMEOUT_MS }, 'RSMVBridge neurological link severed due to timeout.');
76	            resolve(err(new Error(`RSMVBridge timeout: ${operation} exceeded ${TIMEOUT_MS}ms`)));
77	        }, TIMEOUT_MS);
78	
79	        child.on('close', (code) => {
80	            clearTimeout(timer);
81	            _lastLatencyMs = Date.now() - start;
82	
83	            if (code !== 0) {
84	                const msg = stderr.trim() || `Exit code ${code}`;
85	                logger.error({ operation, args, msg }, 'RSMVBridge subprocess failed');
86	                resolve(err(new Error(`RSMVBridge[${operation}] failed: ${msg}`)));
87	                return;
88	            }
89	
90	            try {
91	                const parsed = JSON.parse(stdout.trim()) as T & { error?: string };
92	                if ((parsed as any).error && (parsed as any).error !== 'parse_unavailable') {
93	                    resolve(err(new Error((parsed as any).error)));
94	                } else {
95	                    resolve(ok(parsed));
96	                }
97	            } catch (e: any) {
98	                resolve(err(new Error(`RSMVBridge[${operation}] parse error: ${e.message} (Payload: ${stdout.substring(0, 100)}...)`)));
99	            }
100	        });
101	
102	        child.on('error', (errVal) => {
103	            clearTimeout(timer);
104	            resolve(err(errVal));
105	        });
106	    });
107	}
