213	    /** Probe the live cache. Result is cached for 30s to prevent audit spam. */
214	    public async healthCheck(): Promise<Result<BridgeHealthResult>> {
215	        const now = Date.now();
216	        if (this._lastHealthCheckResult && (now - this._lastHealthCheckTime < 30000)) {
217	            return this._lastHealthCheckResult;
218	        }
219	
220	        try {
221	            const result = await callBridge<BridgeHealthResult>('health');
222	            this._healthy = result.ok && result.value.online;
223	            this._lastHealthCheckTime = now;
224	            this._lastHealthCheckResult = result;
225	            return result;
226	        } catch (e) {
227	            logger.warn({ err: e }, '[RSMVBridge] Health check failed, defaulting to DEGRADED mode to prevent boot stall.');
228	            const degraded = ok({ online: false, reason: 'Substrate diagnostic timeout: ESM resolution conflict.' });
229	            this._healthy = false;
230	            this._lastHealthCheckTime = now;
231	            this._lastHealthCheckResult = degraded;
232	            return degraded;
233	        }
234	    }
